CREATE TABLE public.artwork_uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, title text NOT NULL, kind text NOT NULL CHECK (kind IN ('mural','repeating')), categories text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','generating','ready','paused','failed')), error text, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.artwork_uploads TO authenticated;
GRANT ALL ON public.artwork_uploads TO service_role;
ALTER TABLE public.artwork_uploads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read their uploaded drafts" ON public.artwork_uploads FOR SELECT TO authenticated USING(owner_id = auth.uid());
CREATE TABLE public.artwork_colorways (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), upload_id uuid NOT NULL REFERENCES public.artwork_uploads(id), name text NOT NULL, position integer NOT NULL CHECK(position BETWEEN 0 AND 4), artwork_path text NOT NULL, UNIQUE(upload_id,position));
GRANT SELECT ON public.artwork_colorways TO authenticated;
GRANT ALL ON public.artwork_colorways TO service_role;
ALTER TABLE public.artwork_colorways ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read draft colorways" ON public.artwork_colorways FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.artwork_uploads u WHERE u.id=upload_id AND u.owner_id=auth.uid()));
CREATE TABLE public.artwork_mockups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), colorway_id uuid NOT NULL REFERENCES public.artwork_colorways(id), room integer NOT NULL CHECK(room BETWEEN 0 AND 2), image_path text NOT NULL, UNIQUE(colorway_id,room));
GRANT SELECT ON public.artwork_mockups TO authenticated;
GRANT ALL ON public.artwork_mockups TO service_role;
ALTER TABLE public.artwork_mockups ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read draft room photos" ON public.artwork_mockups FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.artwork_colorways c JOIN public.artwork_uploads u ON u.id=c.upload_id WHERE c.id=colorway_id AND u.owner_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.claim_artwork_mockups(_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.artwork_uploads SET lease_until=now()+interval '15 minutes', status='generating' WHERE id=_id AND status IN ('draft','generating','failed') AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_artwork_mockups(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_artwork_mockups(uuid) TO service_role;
CREATE POLICY "Owners read private artwork files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='designer-artwork' AND (storage.foldername(name))[1]=auth.uid()::text);